function setChrome(){document.documentElement.lang=lang;document.documentElement.dir=lang==='fa'?'rtl':'ltr';document.body.classList.toggle('dark',theme==='dark');$('#previewText').textContent='Lernova';$('#reviewLink').textContent=t('Was ist neu? ↗','چه چیزی تغییر کرده؟ ↗');$('#navLabel').textContent=t('DEIN LERNRAUM','فضای یادگیری تو');$('#nav').innerHTML=[['home','▦','Übersicht','نمای کلی'],['courses','▣','Meine Fächer','درس‌های من'],['flashcards','▱','Karteikarten','فلش‌کارت‌ها'],['quiz','✓','Wissen testen','خودت را امتحان کن'],['progress','◴','Mein Fortschritt','پیشرفت من'],['resources','▤','Materialien & Videos','منابع و ویدیوها'],['settings.html','⚙','Einstellungen','تنظیمات']].map(([r,i,de,fa])=>`<a href="${r.endsWith('.html')?r:'#'+r}" class="${route().split('/')[0]===r||(r==='courses'&&/^(course|lesson)\//.test(route()))?'active':''}"><span class="navicon">${i}</span>${t(de,fa)}${r==='courses'?'<span class="navcount">'+courses().length+'</span>':''}</a>`).join('');$('#sideTitle').textContent=t('Verstehen statt auswendig.','بفهم، فقط حفظ نکن.');$('#sideText').textContent=t('Ein Begriff. Ein Beispiel. Ein kleiner Schritt weiter.','هر مفهوم با یک مثال؛ هر درس یک قدم به جلو.');$('#sideLink').textContent=t('Neue Erklärungen entdecken →','توضیحات تازه را ببین ←');$('#profileLabel').textContent=account.role||t('Dein Profil','پروفایل تو');$('.person strong').textContent=accountName;$$('.avatar').forEach(x=>x.textContent=Array.from(accountName)[0]||'L');$('.person').href='profile.html';$('#logoutBtn').textContent=t('Abmelden','خروج');$('#langBtn').innerHTML=lang==='de'?'فارسی <span>⇄</span>':'Deutsch <span>⇄</span>';$('#themeBtn').setAttribute('aria-label',t('Helles oder dunkles Design','تغییر حالت روشن یا تاریک'));$('#footer').innerHTML=`<span>Lernova · Fachinformatik mit Klarheit.</span><span>${t('Dein Lernportal · Lernfortschritt in diesem Browser','پورتال یادگیری تو · ذخیرهٔ پیشرفت در این مرورگر')}</span>`;$('#crumb').textContent=t('Dein Lernraum / ','فضای یادگیری / ')+(/^(course|lesson)/.test(route())?t('Fächer','درس‌ها'):({home:t('Übersicht','نمای کلی'),courses:t('Fächer','درس‌ها'),flashcards:t('Karteikarten','فلش‌کارت'),quiz:t('Wissen testen','تمرین'),progress:t('Fortschritt','پیشرفت'),review:t('Designvorschau','پیش‌نمایش')}[route()]||'Lernova'));}
