function lessonMedia(c,k){const base=LESSON_VIDEOS[c.id+'/'+k]||(c.id==='it-systeme'&&k==='osi'?LESSON_VIDEOS['osi-modell']:null);return base?`<figure class="lesson-video"><h2>${t('Video zur Lektion','ویدیوی این درس')}</h2><video controls preload="none" playsinline poster="${base}.webp" width="1920" height="1080"><source src="${base}.mp4" type="video/mp4"><track kind="subtitles" src="${base}${base.endsWith('osi-modell')?'.de':''}.vtt" srclang="de" label="Deutsch" default></video><p>${t('Deutsche Tonspur und Untertitel.','گویندگی و زیرنویس آلمانی.')}</p><details class="lesson-transcript"><summary>${t('Transkript · Deutsch','رونوشت · آلمانی')}</summary><pre lang="de" dir="ltr" data-transcript="${base}${base.endsWith('osi-modell')?'.de.vtt':'.srt'}">${t('Wird geladen …','در حال بارگذاری …')}</pre></details></figure>`:''}
