const MOTIVATION = [
 ['Du musst nicht alles wissen. Nur neugierig bleiben.','لازم نیست همه‌چیز را بدانی؛ کنجکاو بمان.','Heute reicht ein Thema, das du wirklich verstehst. Morgen baust du darauf auf.','امروز یک موضوع را درست بفهم؛ فردا می‌توانی روی همان دانش جلوتر بروی.'],
 ['Dein nächster Aha-Moment wartet schon.','لحظهٔ بعدیِ «فهمیدم!» در انتظار توست.','Mit jeder guten Frage wird aus einem schwierigen Thema ein verständlicher Zusammenhang.','با هر سؤال خوب، یک موضوع دشوار به مفهومی قابل‌فهم تبدیل می‌شود.'],
 ['Aus kleinen Schritten wird echtes Können.','قدم‌های کوچک، مهارت واقعی می‌سازند.','Ein Begriff, ein Beispiel, eine Übung. Du musst heute nicht die ganze Prüfung schaffen.','یک مفهوم، یک مثال و یک تمرین؛ لازم نیست امروز همهٔ امتحان را بلد باشی.'],
 ['Du lernst nicht zu langsam. Du lernst gründlich.','آهسته یادگرفتن اشکالی ندارد؛ عمیق یاد بگیر.','Nimm dir die Zeit für das Warum. Verstehen trägt weiter als ein auswendig gelernter Satz.','برای فهمیدن دلیل وقت بگذار؛ فهم عمیق از یک جملهٔ حفظی بیشتر کمکت می‌کند.'],
 ['Heute ein bisschen klarer als gestern.','امروز کمی روشن‌تر از دیروز.','Wiederholen ist kein Rückschritt. So wird Wissen sicher und im Alltag nutzbar.','مرورکردن عقب‌رفتن نیست؛ دانسته‌ها را مطمئن و کاربردی می‌کند.'],
 ['Eine Frage ist oft der beste Anfang.','گاهی یک سؤال بهترین شروع است.','Wenn etwas unklar ist, zerlege es in kleine Teile. Lumo begleitet dich dabei.','اگر چیزی مبهم است، آن را به بخش‌های کوچک تقسیم کن؛ Lumo همراه توست.'],
 ['Deine Zukunft wächst mit deinem Verständnis.','آینده‌ات با دانشت رشد می‌کند.','Du übst für mehr als eine Note: für Situationen, die du später selbst lösen kannst.','برای چیزی بیشتر از نمره تمرین می‌کنی؛ برای مسئله‌هایی که روزی خودت حل می‌کنی.'],
 ['Fehler zeigen dir den nächsten Lernschritt.','اشتباه‌ها قدم بعدی یادگیری را نشان می‌دهند.','Eine falsche Antwort mit guter Erklärung ist eine Gelegenheit, es wirklich zu verstehen.','پاسخ اشتباه با توضیح خوب، فرصتی است تا موضوع را واقعاً بفهمی.'],
 ['Bleib dran. Du baust gerade Können auf.','ادامه بده؛ داری مهارت می‌سازی.','Ein Netzwerk, eine Datenbank, ein gutes Gespräch: Große Aufgaben bestehen aus lernbaren Schritten.','شبکه، پایگاه داده و گفت‌وگوی خوب؛ هر کار بزرگ از قدم‌های قابل‌یادگیری ساخته شده است.'],
 ['Du darfst fragen. Du darfst neu anfangen.','می‌توانی سؤال کنی؛ می‌توانی دوباره شروع کنی.','Wähle einen überschaubaren Abschnitt und gib dir die Chance auf einen kleinen Erfolg.','یک بخش کوچک انتخاب کن و فرصت یک موفقیت کوچک را به خودت بده.'],
 ['Wissen wird stärker, wenn du es anwendest.','دانش با استفاده‌کردن قوی‌تر می‌شود.','Erkläre dir das Beispiel mit eigenen Worten. Dann probiere die Frage ohne Hilfe.','مثال را با زبان خودت توضیح بده؛ سپس سؤال را بدون کمک جواب بده.'],
 ['Dein Tempo. Dein Weg. Dein nächster Schritt.','سرعت تو؛ مسیر تو؛ قدم بعدی تو.','Vergleiche dich mit deinem gestrigen Stand. Jede verstandene Verbindung zählt.','خودت را با دیروزت مقایسه کن؛ هر ارتباطی که می‌فهمی، ارزش دارد.']
];
let motivationIndex;try{motivationIndex=Number(sessionStorage.getItem(userStorage+'motivation')??-1)}catch{motivationIndex=-1}if(motivationIndex<0){motivationIndex=((Number(read('motivation-last',-1))||0)+1)%MOTIVATION.length;try{sessionStorage.setItem(userStorage+'motivation',motivationIndex)}catch{}}
save('motivation-last',motivationIndex);
let lumoLine=0, motionPaused=false, lumoCelebrating=false, lumoResetTimer=null, lumoMoveIndex=0;
function art(){return `<div class="hero-art lumo-garden ${motionPaused?'motion-paused':''}"><span class="lumo-orbit orbit-a" aria-hidden="true">✦</span><span class="lumo-orbit orbit-b" aria-hidden="true">✧</span><span class="lumo-orbit orbit-c" aria-hidden="true">+</span><button class="lumo-character ${lumoCelebrating?'celebrate':''}" id="lumoHello" aria-label="${t('Lumo begrüßen und animieren','به Lumo سلام کن')}"><span class="lumo-speech" role="status">${lumoGreeting()}</span>${LUMO_ORIGINAL_SVG}</button><div class="lumo-caption">${t('Mit Lumo lernt es sich leichter.','با Lumo، یادگیری دل‌نشین‌تر است.')}</div><div class="lumo-motion-actions" role="group" aria-label="${t('Lumos Bewegungen','حرکت‌های Lumo')}">${[['wave',t('Hallo','سلام')],['dance',t('Tanzen','رقص')],['hop',t('Hüpfen','پرش')],['twist',t('Schritte','رقص قدمی')]].map(([m,label])=>`<button type="button" data-lumo-move="${m}">${label}</button>`).join('')}</div></div>`}
function lumoGreeting(){return [t('Hey du. Schön, dass du da bist!','سلام رفیق، چه خوب که اینجایی!'),t('Ganz in Ruhe. Ich bin bei dir.','با آرامش؛ من کنارت هستم.'),t('Ein kleiner Schritt ist auch ein Schritt.','یک قدم کوچک هم ارزش دارد.'),t('Du darfst fragen. Immer.','می‌توانی بپرسی؛ همیشه.'),t('Wir probieren es zusammen.','با هم امتحانش می‌کنیم.'),t('Heute muss nicht alles perfekt sein.','لازم نیست امروز همه‌چیز عالی باشد.'),t('Bereit? Wir gehen in deinem Tempo.','آماده‌ای؟ با سرعت خودت جلو می‌رویم.')][lumoLine%7]}
function celebrateLumo(){const moves=['wave','dance','hop','twist'];playLumoMove(moves[lumoMoveIndex++%moves.length])}
function playLumoMove(move){const b=$('#lumoHello');if(!b)return;const lines={wave:t('Hallo! Schön, dich zu sehen.','سلام! خوشحالم اینجایی.'),dance:t('Eine kleine Tanzpause!','یک رقص کوچولو برای استراحت!'),hop:t('Ein kleiner Freudensprung!','یک پرش کوچولو از خوشحالی!'),twist:t('Schritt für Schritt — mit Rhythmus!','قدم‌به‌قدم، با کمی ریتم!')};b.querySelector('.lumo-speech').textContent=lines[move];window.LumoMotion?.play(move);}
function card(c){let i=info(c),count=c.order.filter(k=>isRevised(c,k)).length;return `<a class="course" href="#course/${esc(c.id)}" style="--tint:${i.color};--ink:${i.ink}"><div class="course-top"><span class="course-icon" aria-hidden="true">${i.icon}</span><span class="tag">${t('Klasse','صنف')} ${c.grade}</span></div><h3>${esc(name(c))}</h3><p>${esc(t(...i.desc))}</p><div class="course-bottom"><span>${c.order.length} ${t('Lektionen','درس')} · ${bankFor(String(c.grade),c.id).length} ${t('Karten','کارت')}</span><span aria-hidden="true">${t('↗','↖')}</span></div></a>`}
function gradeTabs(){return `<div class="tabs" aria-label="${t('Klasse auswählen','انتخاب صنف')}">${['10','11','12'].map(g=>`<button data-grade="${g}" class="${grade===g?'active':''}" aria-pressed="${grade===g}">${t('Klasse','صنف')} ${g}</button>`).join('')}</div>`}
function head(title,desc,extra=''){return `<div class="welcome"><div><p class="eyebrow">FACHINFORMATIK · SYSTEMINTEGRATION</p><h1>${title}</h1><p>${desc}</p></div>${extra}</div>`}
function home(){let cs=courses(),total=cs.reduce((n,c)=>n+c.order.length,0),m=MOTIVATION[motivationIndex];return head(t('Schön, dass du da bist, ','خوش آمدی، ')+esc(accountName)+'.',t('Verstehen, üben, sicherer werden. In deinem Tempo.','بفهم، تمرین کن و مطمئن‌تر شو؛ با سرعت خودت.'),`<span class="datechip">◷ &nbsp; ${t('Jeder Lernschritt zählt','هر قدم یادگیری ارزش دارد')}</span>`)+`<section class="hero"><div class="hero-copy"><div class="eyebrow">${t('DEIN LERNMOMENT','لحظهٔ یادگیری تو')}</div><h2 id="motivationTitle">${esc(t(m[0],m[1]))}</h2><p id="motivationBody">${esc(t(m[2],m[3]))}</p><div class="btn-group"><a href="#courses" class="btn primary">${t('Mein Lernthema finden','انتخاب موضوع یادگیری')} <span>→</span></a><button class="motivation-next" id="nextMotivation" aria-label="${t('Nächsten Mutmacher anzeigen','متن انگیزشی بعدی')}">↻</button></div></div>${art()}</section><div class="overview"><div class="metric"><div class="metric-icon">▣</div><div><strong>${cs.length}</strong><span>${t('Lernbereiche in Klasse','بخش آموزشی در صنف')} ${grade}</span></div></div><div class="metric"><div class="metric-icon">▤</div><div><strong>${total}</strong><span>${t('Erklärte Lektionen','درس با توضیحات')}</span></div></div><div class="metric"><div class="metric-icon">▱</div><div><strong>${bankFor(grade,'all').length}</strong><span>${t('Karten für diese Klasse','کارت برای این صنف')}</span></div></div></div><div class="content-layout"><section><div class="section-head"><div><h2>${t('Deine Lernbereiche','بخش‌های آموزشی تو')}</h2><p>${t('Wähle deine Klasse und starte mit einem Thema.','صنفت را انتخاب کن و با یک موضوع شروع کن.')}</p></div>${gradeTabs()}</div>${grade==='12'?`<p class="curriculum-note">${t('Drei Lernmodule nach LF 10b, 11b und 12b des bayerischen Lehrplans.','سه بخش آموزشی بر اساس LF 10b، 11b و 12b برنامهٔ درسی بایرن.')}</p>`:''}<div class="course-grid">${cs.map(card).join('')}</div></section><aside class="rail"><section class="rail-panel"><h3>${t('Dein Weg zum Verständnis','مسیر تو برای فهم بهتر')}</h3>${[[t('Was ist es?','چیست؟'),t('Begriff und Aufgabe zuerst verstehen.','اول مفهوم و کاربردش را بفهم.')],[t('Wie funktioniert es?','چطور کار می‌کند؟'),t('Die einzelnen Teile und ein Beispiel kennenlernen.','بخش‌ها و یک مثال را قدم‌به‌قدم بخوان.')],[t('Kann ich es erklären?','می‌توانم توضیح بدهم؟'),t('Mit Fragen, Karten und Zuordnung üben.','با سؤال، کارت و بازی تطبیق تمرین کن.')]].map(([a,b],i)=>`<div class="step"><span class="step-num">${i+1}</span><div><strong>${a}</strong><p>${b}</p></div></div>`).join('')}</section><section class="rail-panel rail-note"><h3>✧ ${t('Für deine Prüfungsvorbereitung','برای آمادگی امتحان تو')}</h3><p>${t('Fachwissen aufbauen, Zusammenhänge verstehen und regelmäßig wiederholen. Selbst erstellte Lernfragen – keine offiziellen IHK-Prüfungsaufgaben.','دانش تخصصی بساز، ارتباط‌ها را بفهم و مرتب مرور کن. سؤال‌های اینجا آموزشی‌اند و سؤال رسمی IHK نیستند.')}</p><a class="small-link" href="#flashcards">${t('Klasse gemischt üben →','تمرین عمومی صنف ←')}</a></section></aside></div><div class="study-tools">${[['flashcards','▱',t('Karten & Lernspiele','کارت‌ها و بازی آموزشی'),t('Fach auswählen oder Klasse mischen','انتخاب مضمون یا ترکیب کل صنف')],['quiz','✓',t('Prüfungswissen üben','تمرین برای امتحان'),t('Fragen mit begründeter Lösung','سؤال با دلیل پاسخ درست')],['progress','◴',t('Fortschritt sehen','دیدن پیشرفت'),t('Gelesene Lektionen und Karten','درس‌ها و کارت‌های مرورشده')]].map(([r,i,a,b])=>`<a class="tool" href="#${r}"><span>${i}</span><div><h3>${a}</h3><p>${b}</p></div></a>`).join('')}</div>`}
function catalog(){return head(t('Was möchtest du verstehen?','چه چیزی می‌خواهی یاد بگیری؟'),t('Suche nach einem Fach, Begriff oder Thema.','نام درس، موضوع یا واژهٔ مورد نظر را جست‌وجو کن.'),gradeTabs())+`<label class="searchbar"><span aria-hidden="true">⌕</span><input id="search" type="search" aria-label="${t('Fächer und Lektionen suchen','جست‌وجوی درس‌ها')}" placeholder="${t('z. B. Subnetting, DNS, Datenmodell …','مثلاً Subnetting، DNS یا مدل داده …')}" autocomplete="off"><kbd>↵</kbd></label><div id="searchResults" class="course-grid">${courses().map(card).join('')}</div>`}
function search(q){let query=q.trim().toLocaleLowerCase(),out=[];for(let c of courses()){if(!query||[name(c),c.subject.de,t(...info(c).desc)].join(' ').toLowerCase().includes(query)){out.push(card(c));continue}for(let k of c.order){let l=lesson(c,k);if(l&&[l.title,l.definition,c.de[k]?.title].join(' ').toLowerCase().includes(query))out.push(`<a class="course" href="#lesson/${c.id}/${k}"><div class="course-top"><span class="tag">${esc(name(c))}</span>${badge(c,k)}</div><h3>${esc(l.title)}</h3><p>${esc(l.definition)}</p><div class="course-bottom"><span>${t('Lektion öffnen','بازکردن درس')}</span><span>↗</span></div></a>`)}}$('#searchResults').innerHTML=out.join('')||`<div class="empty">${t('Kein Treffer. Probiere einen anderen Begriff oder eine andere Klasse.','نتیجه‌ای پیدا نشد؛ واژه یا صنف دیگری را امتحان کن.')}</div>`}
function coursePage(c){return `<a class="backlink" href="#courses">${t('← Alle Lernbereiche','همهٔ بخش‌های آموزشی →')}</a>`+head(esc(name(c)),esc(t(...info(c).desc)))+`<div class="course-learning-actions"><a class="btn" href="#flashcards" data-study-course="${c.id}" data-study-grade="${c.grade}">▱ ${t('Karten zu diesem Fach','کارت‌های این مضمون')}</a><a class="btn" href="#quiz" data-quiz-course="${c.id}" data-study-grade="${c.grade}">✓ ${t('Wissen zu diesem Fach testen','تمرین سؤال‌های این مضمون')}</a></div><div class="topic-list">${c.order.map((k,i)=>{let l=lesson(c,k);if(!l)return '';return `<a class="topic-row" href="#lesson/${c.id}/${k}"><span class="topic-number">${done.includes(c.id+'/'+k)?'✓':String(i+1).padStart(2,'0')}</span><div><h3>${esc(l.title)}</h3><p>${t('Was ist es? · Funktion · Beispiel · Übung','چیست؟ · کاربرد · مثال · تمرین')}</p></div><span class="tag">${REVISED[c.id+'/'+k]?.minutes||6} ${t('Min.','دقیقه')}</span><span aria-hidden="true">${t('→','←')}</span></a>`}).join('')}</div>`}
const secLabels=()=>[t('Das lernst du','هدف این درس'),t('Der Grundgedanke','مفهوم اصلی'),t('Schritt für Schritt','توضیح قدم‌به‌قدم'),t('Ein konkretes Beispiel','یک مثال واقعی'),t('Typischer Denkfehler','اشتباه رایج'),t('Die wichtigsten Begriffe','واژه‌های مهم'),t('Kurz merken','نکته‌های کلیدی'),t('Teste dein Verständnis','فهم خودت را امتحان کن')];
function text(s){return esc(s).replace(/((?:\d{1,3}\.){3}\d{1,3}(?:\/\d{1,2})?)/g,'<bdi dir="ltr">$1</bdi>').replace(/(ipconfig \/all|nslookup [a-z.]+|192\.168\.[\d.\/]+)/g,'<bdi dir="ltr">$1</bdi>')}
function osiOverview(){let layers=[
[7,'Anwendung · Application',t('Netzdienste für Anwendungen, zum Beispiel HTTP und DNS.','خدمات شبکه برای برنامه‌ها؛ مانند HTTP و DNS.')],
[6,'Darstellung · Presentation',t('Daten darstellen und umwandeln; konzeptionell auch Kompression und Verschlüsselung.','نمایش و تبدیل داده؛ در مدل مفهومی شامل فشرده‌سازی و رمزنگاری نیز می‌شود.')],
[5,'Sitzung · Session',t('Dialoge und Sitzungen zwischen Kommunikationspartnern organisieren.','سازمان‌دهی گفت‌وگو و نشست بین طرف‌های ارتباط.')],
[4,'Transport · Transport',t('Daten zwischen Anwendungen übertragen; TCP oder UDP und Portnummern.','انتقال بین برنامه‌ها؛ TCP یا UDP و شمارهٔ پورت‌ها.')],
[3,'Vermittlung · Network',t('Pakete zwischen Netzen weiterleiten; IP-Adressen und Routing.','فرستادن بسته‌ها بین شبکه‌ها؛ آدرس IP و مسیریابی.')],
[2,'Sicherung · Data Link',t('Frames über eine lokale Verbindung übertragen; Ethernet, MAC und Switching.','انتقال فریم در اتصال محلی؛ Ethernet، MAC و Switching.')],
[1,'Bitübertragung · Physical',t('Bits als elektrische, optische oder Funksignale übertragen.','انتقال بیت‌ها به شکل سیگنال الکتریکی، نوری یا رادیویی.')]
];return `<div class="osi-layers"><h2>${t('Alle sieben Schichten: von oben nach unten','هر هفت لایه؛ از بالا به پایین')}</h2><div class="osi-direction"><span>${t('Sender','فرستنده')}: <bdi dir="ltr">7 → 1</bdi></span><span>${t('Empfänger','گیرنده')}: <bdi dir="ltr">1 → 7</bdi></span></div>${layers.map(([n,name,body])=>`<div class="osi-layer" style="--layer-hue:${155+(7-n)*13}"><span class="layer-number">${n}</span><div><strong dir="ltr">${name}</strong><p>${body}</p></div></div>`).join('')}<p class="study-note">${t('OSI ist ein Referenzmodell. Reale Internetprotokolle bilden besonders die oberen drei Schichten nicht immer getrennt ab.','OSI یک مدل مرجع است؛ پروتکل‌های واقعی اینترنت، به‌ویژه سه لایهٔ بالایی را همیشه جداگانه پیاده‌سازی نمی‌کنند.')}</p></div>`}
function subnetGraphic(){return `<div class="subnetviz" aria-label="192.168.10.77 liegt im Block 64 bis 127"><div class="blocks"><div>0–63</div><div class="current">64–127<br>↑ .77</div><div>128–191</div><div>192–255</div></div><div class="subnet-labels"><span>192.168.10.0/26</span><span>192.168.10.192/26</span></div></div>`}
function sourceBlock(key){const r=REVISED[key];const sources=[r.source,...(r.additionalSources||[])].filter(x=>Array.isArray(x)&&x.length===2&&/^https:\/\//.test(x[1]));const seen=new Set();return `<div class="source">${t('Zum fachlichen Nachlesen:','منبع برای مطالعهٔ بیشتر:')}<br>${sources.filter(x=>{if(seen.has(x[1]))return false;seen.add(x[1]);return true}).map(([label,url])=>`<a href="${esc(url)}" target="_blank" rel="noopener">${esc(label)} ↗</a>`).join('<br>')}</div>`}
function lessonPage(c,k){let l=lesson(c,k),rev=isRevised(c,k),labels=secLabels(),key=c.id+'/'+k;let sections=[];if(l.goal)sections.push([0,`<div class="goal"><h2>${labels[0]}</h2><p>${text(l.goal)}</p></div>`]);sections.push([1,`<h2>${labels[1]}</h2><p>${text(l.definition)}</p>`]);if(k==='osi')sections.push([2,osiOverview(),t('Sieben Schichten im Überblick','نمای کلی هفت لایه')]);if(l.explanation&&(!l.sections?.length||!l.sections.every(x=>l.explanation.includes(x.body))))sections.push([2,`<h2>${k==='osi'?t('So arbeiten die Schichten zusammen','ارتباط لایه‌ها با یکدیگر'):labels[2]}</h2><p>${text(l.explanation)}</p>`,k==='osi'?t('Zusammenspiel der Schichten','ارتباط لایه‌ها'):labels[2]]);if(l.sections?.length)l.sections.forEach(x=>sections.push([2,`<h2>${text(x.title)}</h2><p>${text(x.body)}</p>`,x.title]));if(l.full&&Array.isArray(l.steps))sections.push([2,`<ol>${l.steps.map(s=>`<li>${text(s)}</li>`).join('')}</ol>`]);if(l.example)sections.push([3,`<div class="example"><h2>${labels[3]}</h2><p>${text(l.example)}</p>${key==='it-systeme/subnet'?subnetGraphic():''}</div>`]);if(l.mistake)sections.push([4,`<div class="warning"><h2>${labels[4]}</h2><p>${text(l.mistake)}</p></div>`]);if(l.terms)sections.push([5,`<h2>${labels[5]}</h2><div class="terms">${l.terms.map(x=>`<div class="term"><strong>${esc(x[0]||x.t)}</strong><p>${text(x[1]||x.d)}</p></div>`).join('')}</div>`]);if(l.remember?.length)sections.push([6,`<h2>${labels[6]}</h2><ul>${l.remember.map(s=>`<li>${text(s)}</li>`).join('')}</ul>${l.summary?`<p><strong>${text(l.summary)}</strong></p>`:''}`]);if(l.q)sections.push([7,`<div class="exercise" id="lessonExercise"><p class="eyebrow">${labels[7]}</p><h3>${text(l.q)}</h3><div class="choices">${l.options.map((o,i)=>`<button class="choice" data-lesson-answer="${i}" data-key="${key}"><span>${String.fromCharCode(65+i)}</span><bdi>${esc(o)}</bdi></button>`).join('')}</div><div id="lessonFeedback" aria-live="polite"></div></div>`]);
return `<a class="backlink" href="#course/${c.id}">${t('← Zur Fachübersicht','بازگشت به فهرست درس‌ها →')}</a><div class="lesson-head"><span class="eyebrow">${esc(name(c))} · ${t('KLASSE','صنف')} ${c.grade}</span><h1>${esc(l.title)}</h1><div class="lesson-meta">${badge(c,k)}${rev?`<span>◷ ${REVISED[key].minutes} ${t('Min. Lernzeit','دقیقه مطالعه')}</span>`:''}<span>DE / فارسی</span></div></div>${!rev?`<div class="notice">${t('Dieser Text ist aus der aktuellen Website übernommen und noch nicht inhaltlich überarbeitet. Die erweiterten Erklärungen findest du in den gekennzeichneten Lektionen.','این متن از سایت فعلی گرفته شده و هنوز بازنویسی محتوایی نشده است. برای توضیح‌های تکمیلی، درس‌های علامت‌گذاری‌شده را ببین.')} <a class="small-link" href="#review">${t('Beispiele ansehen →','دیدن نمونه‌ها ←')}</a></div>`:''}<div class="lesson-layout"><article class="reading">${lessonMedia(c,k)}${sections.map(([i,html],n)=>`<section id="part-${n}">${html}</section>`).join('')}${rev?`${sourceBlock(key)}`:''}<div class="btn-group" style="margin-top:25px"><button class="btn" id="printLesson">${t('Drucken / PDF','چاپ / PDF')}</button><button class="btn primary" id="completeLesson" data-key="${key}">${done.includes(key)?t('✓ Abgeschlossen','✓ تکمیل شده'):t('Als gelesen markieren','علامت‌گذاری به‌عنوان خوانده‌شده')}</button><a class="btn" href="#course/${c.id}">${t('Weitere Lektionen','درس‌های بیشتر')}</a></div></article><aside class="lesson-toc"><h3>${t('IN DIESER LEKTION','در این درس')}</h3>${sections.map(([i,html,title],n)=>`<a href="#part-${n}" data-scroll="part-${n}">${esc(title||labels[i])}</a>`).join('')}<a class="btn" href="#flashcards">${t('Begriffe wiederholen →','مرور واژه‌ها ←')}</a></aside></div>`}
const sampleKeys=Object.keys(REVISED);
/* Study banks, grade/subject filtering and three actual practice modes. */
const CARD_BANK = buildCardBank();
function buildCardBank(){const out=[],seen=new Set();for(const c of CATALOG){for(const k of c.order){const r=REVISED[c.id+'/'+k];if(!r)continue;const d=r.de,f=r.fa;const entries=(d.terms||[]).map((x,i)=>({front:{de:x[0],fa:x[0]},back:{de:x[1],fa:f.terms?.[i]?.[1]||x[1]},type:'term'}));entries.push({front:{de:'Was ist '+d.title+'?',fa:'«'+f.title+'» چیست؟'},back:{de:d.definition,fa:f.definition},type:'concept'});if(d.q)entries.push({front:{de:d.q,fa:f.q},back:{de:d.options[d.answer]+' — '+d.feedback,fa:f.options[f.answer]+' — '+f.feedback},type:'practice'});for(let i=0;i<entries.length;i++){let x=entries[i],identity=c.id+'/'+x.front.de.trim().toLowerCase();if(seen.has(identity))continue;seen.add(identity);out.push({...x,id:c.id+'/'+k+'/'+i,course:c.id,grade:String(c.grade),lesson:c.id+'/'+k})}}}return out}
function bankFor(g,subject='all'){return CARD_BANK.filter(c=>c.grade===g&&(subject==='all'||c.course===subject))}
function shuffled(arr){let copy=[...arr];for(let i=copy.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[copy[i],copy[j]]=[copy[j],copy[i]]}return copy}
let cardGrade=grade,cardSubject='all',cardMode='learn',cardLimit='20',dueOnly=false,studyMemory=read('study-memory',{}),studyDeck=[],studyPos=0,studyFlipped=false,writtenAnswer='',knownThisRound=0,againThisRound=0,matchItems=[],matchSelected=[],matchSolved=[],matchAttempts=0,matchBusy=false;
function deckPool(){let pool=bankFor(cardGrade,cardSubject);return dueOnly?pool.filter(c=>!studyMemory[c.id]?.due||studyMemory[c.id].due<=Date.now()):pool}
function resetStudy(){studyDeck=shuffled(deckPool());if(cardLimit!=='all')studyDeck=studyDeck.slice(0,Number(cardLimit));studyPos=0;studyFlipped=false;writtenAnswer='';knownThisRound=0;againThisRound=0;resetMatch()}
function resetMatch(){let pool=shuffled(deckPool().filter(c=>c.type==='term')),unique=[],seen=new Set();for(let c of pool){if(!seen.has(c.front.de)){unique.push(c);seen.add(c.front.de)}if(unique.length===6)break}matchItems=shuffled(unique.flatMap(c=>[{...c,side:'front'},{...c,side:'back'}]));matchSelected=[];matchSolved=[];matchAttempts=0;matchBusy=false}
function gradeSelect(id,g){return `<select id="${id}" aria-label="${t('Klasse wählen','انتخاب صنف')}">${['10','11','12'].map(n=>`<option value="${n}" ${g===n?'selected':''}>${t('Klasse','صنف')} ${n}</option>`).join('')}</select>`}
function subjectSelect(id,g,subject){return `<select id="${id}" aria-label="${t('Fach wählen','انتخاب مضمون')}"><option value="all">${t('Alle Fächer · Klasse gemischt','همهٔ مضمون‌ها · تمرین عمومی صنف')}</option>${CATALOG.filter(c=>String(c.grade)===g).map(c=>`<option value="${c.id}" ${c.id===subject?'selected':''}>${esc(name(c))}</option>`).join('')}</select>`}
function studyFilterBar(quiz=false){let g=quiz?quizGrade:cardGrade,su=quiz?quizSubject:cardSubject;return `<div class="study-filters"><label><span>${t('Klasse','صنف')}</span>${gradeSelect(quiz?'quizGrade':'cardGrade',g)}</label><label class="subject-filter"><span>${t('Fach / Lernbereich','مضمون / بخش آموزشی')}</span>${subjectSelect(quiz?'quizSubject':'cardSubject',g,su)}</label>${quiz?'':`<label><span>${t('Karten pro Runde','کارت در هر دور')}</span><select id="cardLimit"><option value="10" ${cardLimit==='10'?'selected':''}>10</option><option value="20" ${cardLimit==='20'?'selected':''}>20</option><option value="50" ${cardLimit==='50'?'selected':''}>50</option><option value="all" ${cardLimit==='all'?'selected':''}>${t('Alle Karten','همهٔ کارت‌ها')}</option></select></label>`}</div>`}
function flashcards(){if(!studyDeck.length&&studyPos===0)resetStudy();let pool=bankFor(cardGrade,cardSubject),due=pool.filter(c=>!studyMemory[c.id]?.due||studyMemory[c.id].due<=Date.now()).length;let html=head(t('Dein Wissen. Dein Kartenspiel.','دانش تو؛ بازیِ یادگیری تو.'),t('Wähle eine Klasse, ein Fach oder die ganze Klasse. Lerne, prüfe dich und finde passende Paare.','یک صنف، یک مضمون یا کل صنف را انتخاب کن؛ بخوان، خودت را امتحان کن و جفت‌ها را پیدا کن.'))+studyFilterBar()+`<div class="study-toolbar"><div class="tabs mode-tabs">${[['learn',t('▱ Karteikarten','▱ فلش‌کارت')],['test',t('✓ Selbsttest','✓ خودآزمایی')],['match',t('◇ Paare finden','◇ پیدا کردن جفت‌ها')]].map(([m,title])=>`<button data-card-mode="${m}" class="${cardMode===m?'active':''}" aria-pressed="${cardMode===m}">${title}</button>`).join('')}</div><label class="due-filter"><input type="checkbox" id="dueOnly" ${dueOnly?'checked':''}> ${t('Nur neue & fällige','فقط جدید و موعد مرور')}</label><button class="btn" id="shuffleStudy">↻ ${t('Neu mischen','دوباره مخلوط کن')}</button></div><div class="study-bank-summary"><span><strong>${pool.length}</strong> ${t('Karten in dieser Auswahl','کارت در این انتخاب')}</span><span>${due} ${t('neu oder zur Wiederholung fällig','جدید یا موعد مرور')}</span><span>${t('Insgesamt','مجموع')} ${CARD_BANK.length} ${t('Karten','کارت')}</span></div>`;
if(!deckPool().length&&(!studyDeck.length||cardMode==='match'))return html+`<div class="empty"><h2>${t('Für jetzt alles wiederholt.','فعلاً همه را مرور کرده‌ای.')}</h2><p>${t('Entferne den Fälligkeitsfilter, um alle Karten zu üben.','برای تمرین همهٔ کارت‌ها، فیلتر موعد مرور را بردار.')}</p></div>`;
if(cardMode==='match')return html+matchPage();if(studyPos>=studyDeck.length)return html+`<div class="round-complete"><span class="round-emoji">✦</span><h2>${t('Eine gute Runde. Gut gemacht!','یک دور خوب؛ آفرین به تلاشت!')}</h2><p>${knownThisRound} ${t('sicher beantwortet','پاسخ مطمئن')} · ${againThisRound} ${t('zum Wiederholen markiert','برای مرور دوباره')}</p><button class="btn primary" id="newStudyRound">${t('Nächste Runde starten','شروع دور بعدی')}</button><p class="subtle">${t('Sichere Karten werden später, schwierige Karten früher wieder vorgelegt. Die Speicherung gilt für diesen Browser.','کارت‌های مطمئن دیرتر و کارت‌های دشوار زودتر برای مرور می‌آیند؛ ذخیره‌سازی در همین مرورگر است.')}</p></div>`;
let c=studyDeck[studyPos],course=CATALOG.find(x=>x.id===c.course);return html+`<section class="flash-stage"><div class="section-head"><span class="eyebrow">${t('KARTE','کارت')} ${studyPos+1} / ${studyDeck.length}</span><span class="tag">${esc(name(course))} · ${t('Klasse','صنف')} ${cardGrade}</span></div><div class="progress-track"><div style="width:${studyPos/studyDeck.length*100}%"></div></div>${cardMode==='test'&&studyFlipped&&writtenAnswer?`<div class="your-answer"><strong>${t('Deine Erklärung','توضیح تو')}</strong><p>${text(writtenAnswer)}</p></div>`:''}${cardMode==='test'&&!studyFlipped?`<div class="flash-card selftest-card"><span class="tag">${t('SELBSTTEST · ERST SELBST ERKLÄREN','خودآزمایی · اول با زبان خودت توضیح بده')}</span><strong ${c.type==='term'?'dir="ltr"':''}>${text(c.front[lang])}</strong><textarea id="selfAnswer" aria-label="${t('Deine Antwort, wird nicht automatisch bewertet','پاسخ تو؛ نمره‌دهی خودکار ندارد')}" placeholder="${t('Was weißt du darüber? Schreibe deine Erklärung …','چه چیزی درباره‌اش می‌دانی؟ توضیحت را بنویس …')}">${esc(writtenAnswer)}</textarea><button id="revealStudy" class="btn primary">${t('Mit Mustererklärung vergleichen','مقایسه با توضیح نمونه')}</button></div>`:`<button class="flash-card ${studyFlipped?'is-answer':''}" id="flipStudy" aria-pressed="${studyFlipped}" aria-label="${t('Karte umdrehen','برگرداندن کارت')}"><span class="tag">${studyFlipped?t('ERKLÄRUNG','توضیح'):c.type==='term'?t('FACHBEGRIFF','واژهٔ تخصصی'):t('DENKFRAGE','سؤال مفهومی')}</span>${studyFlipped?`<p>${text(c.back[lang])}</p>`:`<strong ${c.type==='term'?'dir="ltr"':''}>${text(c.front[lang])}</strong>`}<small>${t('Antippen zum Umdrehen ↻','برای برگرداندن، روی کارت بزن ↻')}</small></button>`}<div class="study-rating"><button class="btn rate-again" id="studyAgain" ${!studyFlipped?'disabled':''}>↻ ${t('Noch üben','نیاز به تمرین')}</button><button class="btn primary" id="studyKnown" ${!studyFlipped?'disabled':''}>✓ ${t('Das kann ich','این را بلدم')}</button></div><div class="flash-controls"><button class="small-link as-button" id="skipStudy">${t('Karte überspringen','ردکردن این کارت')}</button><a class="small-link" href="#lesson/${c.lesson}">${t('In der Lektion nachlesen →','توضیح کامل درس ←')}</a></div><p class="study-note">${t('Beantworte die Frage zuerst selbst. Vergleiche dann mit der Erklärung und bewerte ehrlich. Der schriftliche Selbsttest wird nicht automatisch benotet.','اول خودت جواب بده؛ سپس توضیح را ببین و صادقانه میزان یادگیری‌ات را مشخص کن. خودآزمایی نوشتاری نمره‌دهی خودکار ندارد.')}</p></section>`}
function rateStudy(known){const c=studyDeck[studyPos];if(!c||!studyFlipped)return;let old=studyMemory[c.id]||{level:0};let level=known?Math.min(5,(old.level||0)+1):0;studyMemory[c.id]={level,due:Date.now()+(known?[1,1,3,7,14,30][level]*86400000:60000),last:Date.now()};save('study-memory',studyMemory);if(known)knownThisRound++;else againThisRound++;studyPos++;studyFlipped=false;writtenAnswer='';render(true)}
function matchPage(){if(!matchItems.length)resetMatch();let pairs=matchItems.length/2;return `<section class="match-section"><div class="section-head"><div><h2>${t('Welcher Begriff passt zur Erklärung?','کدام واژه با این توضیح جور است؟')}</h2><p>${t('Wähle einen Begriff und die passende Erklärung.','یک واژه و توضیح مناسب آن را انتخاب کن.')}</p></div><span class="tag" role="status">${matchSolved.length} / ${pairs} · ${matchAttempts} ${t('Versuche','تلاش')}</span></div><div class="match-grid">${matchItems.map((c,i)=>`<button class="match-tile ${c.side==='front'?'term-tile':'definition-tile'} ${matchSelected.includes(i)?'selected':''} ${matchSolved.includes(c.id)?'matched':''}" id="match-${i}" data-match="${i}" ${matchSolved.includes(c.id)?'disabled':''} aria-pressed="${matchSelected.includes(i)}"><span class="tag">${c.side==='front'?t('Begriff','واژه'):t('Erklärung','توضیح')}</span><span ${c.side==='front'?'dir="ltr"':''}>${text(c.side==='front'?c.front[lang]:c.back[lang])}</span>${matchSolved.includes(c.id)?'<span class="match-check">✓</span>':''}</button>`).join('')}</div><div id="matchFeedback" role="status" aria-live="polite" class="study-note">${matchSolved.length===pairs?t('Alle Paare gefunden. Stark!','همهٔ جفت‌ها را پیدا کردی!'):t('Gleiche Farbe ist kein Hinweis. Der Inhalt entscheidet.','رنگ‌ها جواب را مشخص نمی‌کنند؛ به مفهوم دقت کن.')}</div><button class="btn primary" id="newMatch">${t('Neue Paare spielen','بازی با جفت‌های جدید')}</button></section>`}
function chooseMatch(index){if(matchBusy||matchSelected.includes(index)||matchSolved.includes(matchItems[index]?.id))return;matchSelected.push(index);if(matchSelected.length===2){matchAttempts++;let[a,b]=matchSelected.map(i=>matchItems[i]);if(a.id===b.id&&a.side!==b.side){matchSolved.push(a.id);matchSelected=[];render(true)}else{matchBusy=true;render(true);$('#matchFeedback').textContent=t('Diese beiden passen noch nicht. Versuche es erneut.','این دو با هم جور نیستند؛ دوباره امتحان کن.');setTimeout(()=>{matchSelected=[];matchBusy=false;if(route()==='flashcards'&&cardMode==='match')render(true)},850)}}else render(true)}
let quizGrade=grade,quizSubject='all',quizDeck=[],qi=0,selected=null,checked=false,answers=[];
function resetQuiz(){quizDeck=shuffled(Object.keys(REVISED).filter(k=>{let cid=k.split('/')[0],c=CATALOG.find(c=>c.id===cid);return c&&String(c.grade)===quizGrade&&(quizSubject==='all'||quizSubject===cid)&&REVISED[k][lang]?.q})).slice(0,20);qi=0;selected=null;checked=false;answers=[]}
function quizPage(){if(!quizDeck.length)resetQuiz();const filter=studyFilterBar(true)+`<div class="notice">${t('Selbst erstellte Übungsfragen mit erklärten Lösungen. Sie unterstützen die IHK-Vorbereitung und ersetzen weder den vollständigen Prüfungskatalog noch Originalprüfungen.','سؤال‌های تمرینی تألیفی با توضیح پاسخ؛ برای کمک به آمادگی IHK هستند و جایگزین فهرست کامل مطالب یا امتحان‌های اصلی نیستند.')}</div>`;if(qi>=quizDeck.length){let score=answers.filter(Boolean).length;return head(t('Jetzt weißt du, was schon sitzt.','حالا می‌دانی چه چیزهایی را بلد هستی.'),t('Nutze die Erklärungen, um unsichere Themen gezielt zu wiederholen.','با توضیح‌ها، موضوع‌هایی را که هنوز مطمئن نیستی مرور کن.'))+filter+`<div class="reading"><h2>${score} / ${quizDeck.length} ${t('richtig','پاسخ درست')}</h2>${quizDeck.map((k,i)=>`<p style="margin-top:18px">${answers[i]?'✓':'○'} ${esc(REVISED[k][lang].title)} <a class="small-link" href="#lesson/${k}">${t('Lektion ansehen →','دیدن درس ←')}</a></p>`).join('')}<button class="btn primary" id="restartQuiz" style="margin-top:25px">${t('Neue Fragen mischen','تمرین سؤال‌های جدید')}</button></div>`}let l=REVISED[quizDeck[qi]][lang];return head(t('Verstanden? Probier es aus.','فهمیدی؟ امتحان کن.'),t('Passende Fragen zu deiner Klasse und deinem Fach. Ohne Zeitdruck.','سؤال‌های مربوط به صنف و مضمون خودت؛ بدون محدودیت زمان.'))+filter+`<div class="flash-stage"><div class="section-head"><span class="eyebrow">${t('FRAGE','سؤال')} ${qi+1} / ${quizDeck.length}</span><span class="tag">${esc(l.title)}</span></div><div class="progress-track"><div style="width:${qi/quizDeck.length*100}%"></div></div><section class="reading exercise"><h2>${text(l.q)}</h2><div class="choices">${l.options.map((o,i)=>`<button class="choice ${selected===i?'selected':''} ${checked&&i===l.answer?'correct':''}" data-quiz-answer="${i}" ${checked?'disabled':''} aria-pressed="${selected===i}"><span>${String.fromCharCode(65+i)}</span><bdi>${esc(o)}</bdi></button>`).join('')}</div>${checked?`<div class="feedback ${selected===l.answer?'':'wrong'}" role="status"><strong>${selected===l.answer?t('Richtig.','درست است.'):t('Noch nicht ganz.','هنوز درست نیست.')}</strong><br>${text(l.feedback)}</div><a class="small-link" href="#lesson/${quizDeck[qi]}">${t('Erklärung in der Lektion lesen →','توضیح کامل درس ←')}</a><br><button class="btn primary" id="nextQuestion" style="margin-top:20px">${qi===quizDeck.length-1?t('Ergebnis ansehen','دیدن نتیجه'):t('Nächste Frage →','سؤال بعدی ←')}</button>`:`<button class="btn primary" id="checkAnswer" style="margin-top:20px" ${selected===null?'disabled':''}>${t('Antwort prüfen','بررسی پاسخ')}</button>`}</section></div>`}
function progressPage(){let learned=CARD_BANK.filter(c=>studyMemory[c.id]?.last).length,secure=CARD_BANK.filter(c=>studyMemory[c.id]?.level>=3).length;return head(t('Dein Fortschritt zählt.','پیشرفتت مهم است.'),t('Sieh, was du gelesen und geübt hast. Jeder Schritt ist ein Anfang für den nächsten.','ببین چه چیزهایی را خوانده و تمرین کرده‌ای؛ هر قدم، پایهٔ قدم بعدی است.'))+`<div class="overview"><div class="metric"><div class="metric-icon">✓</div><div><strong>${done.length}</strong><span>${t('Als gelesen markierte Lektionen','درس علامت‌گذاری‌شده به‌عنوان خوانده‌شده')}</span></div></div><div class="metric"><div class="metric-icon">▱</div><div><strong>${learned}</strong><span>${t('Mit Selbsteinschätzung geübte Karten','کارت تمرین‌شده با خودارزیابی')}</span></div></div><div class="metric"><div class="metric-icon">✦</div><div><strong>${secure}</strong><span>${t('Mindestens dreimal sicher bewertet','حداقل سه بار مطمئن ارزیابی‌شده')}</span></div></div></div><div class="notice">${t('Deine Selbsteinschätzung ist keine Prüfungsnote. Vorschau und Original haben getrennte Lernstände; die Speicherung gilt nur für diesen Browser.','خودارزیابی تو نمرهٔ امتحان نیست. پیشرفت پیش‌نمایش و سایت اصلی جداست و فقط در این مرورگر ذخیره می‌شود.')}</div><div class="reading"><h2>${t('Deine gelesenen Lektionen','درس‌های خوانده‌شدهٔ تو')}</h2>${done.length?done.map(key=>{let[cid,k]=key.split('/'),c=CATALOG.find(x=>x.id===cid);if(!c||!lesson(c,k))return '';return `<a class="topic-row" style="margin-top:12px" href="#lesson/${key}"><span>✓</span><div><h3>${esc(lesson(c,k).title)}</h3><p>${esc(name(c))} · ${t('Klasse','صنف')} ${c.grade}</p></div></a>`}).join(''):`<p style="margin:15px 0 22px">${t('Noch keine Lektion markiert. Wähle ein Thema, lies die Erklärung und markiere die Lektion anschließend.','هنوز درسی علامت نزده‌ای. یک موضوع را انتخاب کن، توضیح را بخوان و سپس آن را علامت‌گذاری کن.')}</p><a class="btn primary" href="#courses">${t('Ein Thema auswählen','انتخاب موضوع')}</a>`}</div>`}
function render(keepScroll=false){$$('video').forEach(v=>v.pause());const focusId=keepScroll?document.activeElement?.id:null;setChrome();let r=route(),parts=r.split('/'),html;if(r==='home')html=home();else if(r==='courses')html=catalog();else if(r==='flashcards')html=flashcards();else if(r==='quiz')html=quizPage();else if(r==='progress')html=progressPage();else if(r==='resources'||r==='review')html=resourcesPage();else if(parts[0]==='course'){let c=CATALOG.find(c=>c.id===parts[1]);html=c?coursePage(c):notFound()}else if(parts[0]==='lesson'){let c=CATALOG.find(c=>c.id===parts[1]);html=c&&lesson(c,parts[2])?lessonPage(c,parts[2]):notFound()}else html=notFound();$('#main').innerHTML=html;document.title=(r==='home'?t('Dein Lernraum','فضای یادگیری تو'):$('#main h1')?.textContent||'Lernova')+' · Lernova';if(!keepScroll)window.scrollTo(0,0);$('#sidebar').classList.remove('open');$('#menuBtn').setAttribute('aria-expanded','false');$('#search')?.addEventListener('input',e=>search(e.target.value));if(focusId)document.getElementById(focusId)?.focus({preventScroll:true});window.LumoMotion?.mount()}
function notFound(){return `<div class="empty"><h1>${t('Seite nicht gefunden','صفحه پیدا نشد')}</h1><a class="btn" href="#home">${t('Zur Übersicht','بازگشت به خانه')}</a></div>`}
function toast(s){$('#toast').textContent=s;$('#toast').hidden=false;setTimeout(()=>$('#toast').hidden=true,3500)}
$('#langBtn').onclick=()=>{lang=lang==='de'?'fa':'de';save('lang',lang);render(true)};
$('#themeBtn').onclick=()=>{theme=theme==='light'?'dark':'light';save('theme',theme);setChrome()};
$('#menuBtn').onclick=()=>{let open=$('#sidebar').classList.toggle('open');$('#menuBtn').setAttribute('aria-expanded',String(open))};
document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#sidebar').classList.remove('open');$('#menuBtn').setAttribute('aria-expanded','false')}});
document.addEventListener('input',e=>{if(e.target.id==='selfAnswer')writtenAnswer=e.target.value});
document.addEventListener('change',e=>{let id=e.target.id,value=e.target.value;if(id==='cardGrade'){cardGrade=value;cardSubject='all';resetStudy();render(true)}if(id==='cardSubject'){cardSubject=value;resetStudy();render(true)}if(id==='cardLimit'){cardLimit=value;resetStudy();render(true)}if(id==='dueOnly'){dueOnly=e.target.checked;resetStudy();render(true)}if(id==='quizGrade'){quizGrade=value;quizSubject='all';resetQuiz();render(true)}if(id==='quizSubject'){quizSubject=value;resetQuiz();render(true)}});
document.addEventListener('click',e=>{let b=e.target.closest('button,a');if(!b)return;
if(b.dataset.grade){grade=b.dataset.grade;save('grade-v2',grade);cardGrade=grade;cardSubject='all';quizGrade=grade;quizSubject='all';resetStudy();resetQuiz();render(true)}
if(b.dataset.scroll){e.preventDefault();document.getElementById(b.dataset.scroll)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}
if(b.id==='nextMotivation'){motivationIndex=(motivationIndex+1)%MOTIVATION.length;save('motivation-last',motivationIndex);let m=MOTIVATION[motivationIndex];$('#motivationTitle').textContent=t(m[0],m[1]);$('#motivationBody').textContent=t(m[2],m[3])}
if(b.id==='printLesson')window.print();if(b.id==='lumoHello')celebrateLumo();if(b.dataset.lumoMove)playLumoMove(b.dataset.lumoMove);
if(b.dataset.studyCourse){cardSubject=b.dataset.studyCourse;cardGrade=b.dataset.studyGrade;resetStudy()}
if(b.dataset.quizCourse){quizSubject=b.dataset.quizCourse;quizGrade=b.dataset.studyGrade;resetQuiz()}
if(b.dataset.cardMode){cardMode=b.dataset.cardMode;studyFlipped=false;writtenAnswer='';resetMatch();render(true)}
if(b.id==='flipStudy'||b.id==='revealStudy'){studyFlipped=!studyFlipped;render(true)}
if(b.id==='studyAgain')rateStudy(false);if(b.id==='studyKnown')rateStudy(true);
if(b.id==='skipStudy'){studyPos++;studyFlipped=false;writtenAnswer='';render(true)}
if(['shuffleStudy','newStudyRound'].includes(b.id)){resetStudy();render(true)}
if(b.id==='newMatch'){resetMatch();render(true)}if(b.dataset.match!==undefined)chooseMatch(Number(b.dataset.match));
if(b.id==='completeLesson'){let key=b.dataset.key;try{let a=JSON.parse(localStorage.getItem('fisi-activity')||'{}'),[c,k]=key.split('/');a[c+'.html']??={};a[c+'.html'][k]={...(a[c+'.html'][k]||{}),opened:true,checked:true,updated:Date.now()};if(account.role!=='guest')localStorage.setItem('fisi-activity',JSON.stringify(a))}catch{}if(!done.includes(key)){done.push(key);save('done',done)}b.textContent=t('✓ Abgeschlossen','✓ تکمیل شده');toast(t('Lernfortschritt gespeichert.','پیشرفتت ذخیره شد.'))}
if(b.dataset.lessonAnswer!==undefined){let l=REVISED[b.dataset.key][lang],n=Number(b.dataset.lessonAnswer);$$('#lessonExercise .choice').forEach(x=>{x.classList.remove('selected','correct');x.setAttribute('aria-pressed','false')});b.setAttribute('aria-pressed','true');b.classList.add(n===l.answer?'correct':'selected');$('#lessonFeedback').className='feedback '+(n===l.answer?'':'wrong');$('#lessonFeedback').textContent=(n===l.answer?t('Richtig. ','درست است. '):t('Noch nicht ganz. ','هنوز درست نیست. '))+l.feedback}
if(b.dataset.quizAnswer!==undefined&&!checked){selected=Number(b.dataset.quizAnswer);render(true)}
if(b.id==='checkAnswer'&&selected!==null){checked=true;answers[qi]=selected===REVISED[quizDeck[qi]][lang].answer;render(true)}
if(b.id==='nextQuestion'){qi++;selected=null;checked=false;render()}
if(b.id==='restartQuiz'){resetQuiz();render()}});
document.addEventListener('pointerout',e=>{let b=e.target.closest?.('.lumo-character');if(b&&!b.contains(e.relatedTarget)){b.style.setProperty('--look-x','0px');b.style.setProperty('--look-y','0px')}});
document.addEventListener('pointermove',e=>{const b=e.target.closest('.lumo-character');if(!b||motionPaused||matchMedia('(prefers-reduced-motion: reduce)').matches)return;let rect=b.getBoundingClientRect(),x=Math.max(-3,Math.min(3,(e.clientX-rect.left-rect.width/2)/25)),y=Math.max(-2,Math.min(2,(e.clientY-rect.top-rect.height/2)/35));b.style.setProperty('--look-x',x+'px');b.style.setProperty('--look-y',y+'px')});
window.addEventListener('hashchange',()=>{render();$('#main').focus({preventScroll:true})});render();

document.addEventListener('toggle',async e=>{if(!e.target.matches?.('.lesson-transcript')||!e.target.open)return;const pre=e.target.querySelector('[data-transcript]');if(!pre||pre.dataset.loaded)return;try{const res=await fetch(pre.dataset.transcript);if(!res.ok)throw Error();pre.textContent=(await res.text()).replace(/\r/g,'').split(/\n\n+/).map(b=>b.split('\n').filter(l=>l.trim()&&!/^WEBVTT|^\d+$|-->/i.test(l)).join('\n')).join('\n\n');pre.dataset.loaded='1'}catch{pre.textContent=t('Transkript konnte nicht geladen werden.','رونوشت بارگذاری نشد.')}},true);
$('#logoutBtn').onclick=()=>{window.LernovaSB?.signOutLocal();sessionStorage.removeItem('fisi-auth');sessionStorage.removeItem(userStorage+'motivation');location.href='login.html'};
if('serviceWorker' in navigator)navigator.serviceWorker.register('sw.js',{scope:'./',updateViaCache:'none'}).catch(()=>{});
